/**
 * Shared SVG builder for the stick-figure library.
 *
 * Figures are authored once as neutral (male) *poses* — a head, a straight
 * skeleton `d` string, a hip point, and optional props — then `buildFigure`
 * generates the four character variants (male / female / boy / girl) from that
 * single source:
 *   • every variant → a face (eyes + mouth, `neutral` unless the pose says
 *                     otherwise) and a variant-appropriate hair style, both
 *                     generated by ./face.ts from the head circle alone
 *   • female / girl → a skirt over the thighs
 *   • boy / girl    → enlarge the head and vertically compress the body so the
 *                     head-to-body ratio reads as a child
 *
 * Authoring conventions: viewBox 0 0 140 260, figure centred near x = 70, bold
 * uniform outline (#1f2937), hollow parts (root `fill="none"`), props set their
 * own fill. Limbs are smoothed into bezier curves so a selected limb already has
 * editable handles.
 */
import { faceHairSvg, faceStateAttrs, asFaceStyle, asHairStyle, type FaceOpts, type FaceStyle, type HairStyle } from './face';
import {
    garmentSvg, garmentStateAttrs, legChains, upperBody,
    asTrouserStyle, asShoeStyle, asTopStyle, asNeckStyle, LEG_UNIT,
    type GarmentOpts, type TrouserStyle,
} from './garments';

export const W = 140, H = 260;
export const STROKE = '#1f2937';

export type Variant = 'male' | 'female' | 'boy' | 'girl';
export const VARIANTS: Variant[] = ['male', 'female', 'boy', 'girl'];

/** Hair style each character variant wears unless the caller overrides it. */
export const VARIANT_HAIR: Record<Variant, HairStyle> = {
    male: 'short', female: 'fringe', boy: 'spiky', girl: 'pigtails',
};

/**
 * Trousers each variant wears by default. Deliberately matches what the library looked
 * like BEFORE garments existed: the feminine variants had a skirt, everyone else was
 * bare-legged. Trousers are opt-in, so no existing figure, template or comic changes
 * appearance — the skirt just now comes from the shared garment system instead of a
 * one-off helper.
 */
export const VARIANT_TROUSERS: Record<Variant, TrouserStyle> = {
    male: 'none', female: 'skirt', boy: 'none', girl: 'skirt',
};

const r1 = (n: number) => Math.round(n * 10) / 10;

/** Wrap markup in a consistent SVG document. */
export function doc(inner: string): string {
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" fill="none" stroke="${STROKE}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
}

/** Head circle at (cx,cy) radius r. Tagged `head` for per-part recolour.
 *  `fill` (opt-in) makes the head solid white so a face reads over busy art;
 *  `state` stamps which face/hair it wears so it can be restyled later. */
export const head = (cx = 70, cy = 34, r = 22, fill = false, state = '') =>
    `<circle cx="${r1(cx)}" cy="${r1(cy)}" r="${r1(r)}"${fill ? ' fill="#ffffff"' : ''} data-sf-role="head"${state}/>`;

/** Parse an `M…L…L…` subpath (only M/L commands) into a list of [x,y] points. */
function subToPoints(sub: string): number[][] {
    return sub.replace(/^M/, '').split('L')
        .map(s => s.trim().split(/[ ,]+/).map(Number))
        .filter(p => p.length === 2 && p.every(Number.isFinite));
}

/** Smooth a straight/polyline limb into a bezier path (subtle bow / Catmull-Rom). */
function curveLimb(points: number[][], bow = 0.05): string {
    if (points.length < 2) return '';
    if (points.length === 2) {
        const [a, b] = points;
        const dx = b[0] - a[0], dy = b[1] - a[1];
        const len = Math.hypot(dx, dy) || 1;
        const off = len * bow;
        const cx = (a[0] + b[0]) / 2 - (dy / len) * off;
        const cy = (a[1] + b[1]) / 2 + (dx / len) * off;
        return `M${a[0]} ${a[1]}Q${r1(cx)} ${r1(cy)} ${b[0]} ${b[1]}`;
    }
    let d = `M${points[0][0]} ${points[0][1]}`;
    for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i - 1] || points[i];
        const p1 = points[i];
        const p2 = points[i + 1];
        const p3 = points[i + 2] || p2;
        const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
        const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
        d += `C${r1(c1x)} ${r1(c1y)} ${r1(c2x)} ${r1(c2y)} ${p2[0]} ${p2[1]}`;
    }
    return d;
}

/**
 * Skeleton from a straight `d` string. Each `M…` subpath (torso, each arm, each
 * leg) becomes its OWN smooth-curved `<path>` — so after ungrouping a dropped
 * figure every limb is independently selectable, stylable, and already a bezier
 * curve with handles. All tagged `body` for role recolour.
 */
export const bones = (d: string, hip?: readonly [number, number]) => {
    // Leg subpaths are tagged so a dropped figure can have its trousers restyled later:
    // garments are derived from the LEG polylines the way a face is derived from the
    // head circle, and once the figure is flattened to paths that is the only way back.
    //
    // A subpath counts as a leg when its FIRST point lies on a leg chain. Matching the
    // chain's start alone isn't enough: seated poses author a leg as thigh + shin, and
    // the shin subpath starts at the KNEE, so it would be left untagged and lose its
    // trouser. Checking the first point only (never the last) keeps the torso out — it
    // ends at the hip but starts at the neck.
    const chainPts = hip ? legChains(d, hip).flat() : [];
    const onLeg = (p: number[]) => chainPts.some(q => Math.hypot(q[0] - p[0], q[1] - p[1]) < 1);
    const ub = hip ? upperBody(d, hip) : null;
    const key = (p: number[][]) => p.map(q => `${q[0]},${q[1]}`).join(' ');
    const torsoKey = ub ? key(ub.torso) : null;
    const armKeys = new Set((ub?.arms ?? []).map(key));
    return d.split(/(?=M)/).map(seg => seg.trim()).filter(Boolean)
        .map(seg => {
            const pts = subToPoints(seg);
            const k = key(pts);
            const part = pts.length === 0 ? ''
                : onLeg(pts[0]) ? 'leg'
                : k === torsoKey ? 'torso'
                : armKeys.has(k) ? 'arm' : '';
            const curved = curveLimb(pts);
            return curved ? `<path d="${curved}" data-sf-role="body"${part ? ` data-sf-part="${part}"` : ''}/>` : '';
        })
        .filter(Boolean).join('');
};

/** A pose: neutral source geometry that variants are generated from. */
export interface Pose {
    id: string;
    name: string;
    category: string;
    tags: string[];
    /** Head circle [cx, cy, r]. */
    head: [number, number, number];
    /** Hip point [x, y] where legs diverge — used to place the skirt. */
    hip: [number, number];
    /** Straight skeleton `d` string (torso + arms + legs as `M…L…` subpaths). */
    bones: string;
    /** Extra prop markup (already coloured / role-tagged). */
    props?: string;
    /** Expression this pose wears by default (e.g. `sad` for the slumped pose). */
    face?: FaceStyle;
    /**
     * Whether to generate female/boy/girl variants. Default true. Set false for
     * seated / behind-object poses where a skirt or child squash makes no sense
     * (they ship as the single neutral figure only).
     */
    variants?: boolean;
}

/** Inner markup (no `<svg>` wrapper) for a pose in a variant — for composing scenes. */
export function figureInner(pose: Pose, variant: Variant = 'male', opts: FaceOpts & GarmentOpts = {}): string {
    return buildFigure(pose, variant, opts).replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
}

/**
 * Build the SVG for a pose in a given character variant.
 *
 * `opts` overrides the face/hair the variant would otherwise wear — the pose's
 * own `face` (or `neutral`) and {@link VARIANT_HAIR}.
 */
export function buildFigure(
    pose: Pose,
    variant: Variant = 'male',
    opts: FaceOpts & GarmentOpts = {},
): string {
    const [cx, cy, r] = pose.head;
    const child = variant === 'boy' || variant === 'girl';
    const rr = child ? r * 1.28 : r;

    // Garments are derived from the pose's OWN leg polylines, so they bend with it.
    // Emitted before the skeleton so the black bone lines draw on top.
    const garment: GarmentOpts = {
        trousers: asTrouserStyle(opts.trousers ?? VARIANT_TROUSERS[variant], 'none'),
        trouserColor: opts.trouserColor,
        shoes: asShoeStyle(opts.shoes, 'none'),
        shoeColor: opts.shoeColor,
        top: asTopStyle(opts.top, 'none'),
        topColor: opts.topColor,
        neck: asNeckStyle(opts.neck, 'none'),
        neckColor: opts.neckColor,
        upper: upperBody(pose.bones, pose.hip) ?? undefined,
        unit: LEG_UNIT,
    };
    const legs = legChains(pose.bones, pose.hip);
    const garments = garmentSvg(legs, pose.hip, garment);

    let bodyInner = garments + bones(pose.bones, pose.hip) + (pose.props || '');
    // Child: vertically compress the body about the neck so the head reads bigger.
    const body = child
        ? `<g transform="translate(0 ${r1(cy + r)}) scale(1 0.82) translate(0 ${r1(-(cy + r))})">${bodyInner}</g>`
        : bodyInner;

    // Head (enlarged for children) + hair + face, all derived from the head circle.
    const face: FaceOpts = {
        face: asFaceStyle(opts.face ?? pose.face, 'neutral'),
        hair: asHairStyle(opts.hair ?? VARIANT_HAIR[variant], 'none'),
        hairColor: opts.hairColor,
        headFill: opts.headFill,
    };
    const headGroup = head(cx, cy, rr, !!opts.headFill, faceStateAttrs(face) + garmentStateAttrs(garment))
        + faceHairSvg(cx, cy, rr, face);

    return doc(body + headGroup);
}
